export type PriceGroup = string;

/** Slug'ın hangi fiyat sistemine ait olduğunu döndürür (ör. "dolgu", "porselen"). */
export function getPriceGroup(slug: string): PriceGroup | null {
  if (!slug.includes("fiyat") && !slug.includes("fiyati")) return null;
  for (const [pattern, key] of PRICE_SYSTEMS) {
    if (slug.includes(pattern)) return key;
  }
  return null;
}

/** Aynı fiyat sistemindeki diğer sayfaların slug'larını döndürür (kendisi hariç). */
export function getRelatedPriceSlugs(slug: string): string[] {
  const group = getPriceGroup(slug);
  if (!group) return [];

  const related = new Set<string>();
  services.forEach((s) => {
    if (s.slug === slug || s.category !== "fiyat") return;
    if (getPriceGroup(s.slug) === group) related.add(s.slug);
  });

  return [...related];
}

